import 'dart:io';import 'package:flutter/material.dart';import '../services/vault_store.dart';import '../models/vault_item.dart';
class VaultScreen extends StatefulWidget{const VaultScreen({super.key});@override State<VaultScreen> createState()=>_VaultState();}
class _VaultState extends State<VaultScreen>{Future<List<VaultItem>> load()=>VaultStore.items();String fmt(int n)=>n<1024?'$n B':n<1048576?'${(n/1024).toStringAsFixed(1)} KB':'${(n/1048576).toStringAsFixed(2)} MB';@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Vault')),body:FutureBuilder<List<VaultItem>>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final items=s.data!;if(items.isEmpty)return const Center(child:Text('Your vault is empty.'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(c,i){final v=items[i];return Card(child:ListTile(leading:const Icon(Icons.folder_copy_outlined),title:Text(v.name,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text('${v.type} · ${fmt(v.bytes)} · ${v.method}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await VaultStore.remove(v);setState((){});})));});}));}
